package com.greenocean.backend;
import com.greenocean.backend.listener.planning.*;import com.greenocean.backend.listener.live.*;import com.greenocean.backend.auth.repository.UserRepository;import com.greenocean.backend.auth.service.*;import com.greenocean.backend.account.repository.AccountRepository;import com.greenocean.backend.identity.AccessPolicy;import com.greenocean.backend.messaging.repository.MessagingRepository;
import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;import org.springframework.jdbc.core.JdbcTemplate;
import org.junit.jupiter.api.*;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;
@SpringBootTest(properties={"greenocean.live-support.enabled=true","greenocean.listener-support.duration-enabled=true","greenocean.listener-support.scheduling-enabled=true","greenocean.listener-support.booking-enabled=true","greenocean.listener-support.followup-enabled=true","greenocean.listener-support.extension-enabled=true"}) @org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc @ActiveProfiles("test") @Transactional
class PhaseN3SessionsTest {
 @Autowired JdbcTemplate db;@Autowired UserRepository users;@Autowired TokenService tokens;@Autowired ListenerSessions sessions;@Autowired ListenerSupportPolicy p;@Autowired LiveSupportService live;@Autowired ListenerCalendar calendar;@Autowired ListenerBookings bookings;@Autowired ListenerSupportMaintenance maintenance;@Autowired AccountRepository accounts;@Autowired AccessPolicy access;@Autowired LiveSupportSettings settings;@Autowired AuthRateLimit rates;@Autowired MessagingRepository messaging;
 @Autowired org.springframework.test.web.servlet.MockMvc mvc;
 PhaseIFixtures.Actor member,listener,staff;Instant start;
 @BeforeEach void setup(){PhaseIFixtures.region(db);member=PhaseIFixtures.member(db,users,tokens);listener=PhaseIFixtures.member(db,users,tokens);staff=PhaseIFixtures.member(db,users,tokens);PhaseIFixtures.review(db,listener.id(),staff.id(),true);live.setAvailability(listener.id(),listener.session(),0,true,null);start=p.now().plusSeconds(7200).truncatedTo(java.time.temporal.ChronoUnit.MINUTES);window(start,start.plusSeconds(14400));}
 void window(Instant a,Instant b){calendar.exception(listener.id(),new ListenerCalendar.ExceptionInput("UTC",a.atOffset(ZoneOffset.UTC).toLocalDateTime().toString(),b.atOffset(ZoneOffset.UTC).toLocalDateTime().toString(),null,null,true));}
 LiveSupportView active(){var r=live.create(member.id(),UUID.randomUUID(),listener.id());live.accept(r.id(),listener.id());return live.activate(r.id(),member.id());}
 void clock(Instant at){db.execute("CREATE OR REPLACE FUNCTION listener_support_now() RETURNS TIMESTAMPTZ LANGUAGE SQL VOLATILE AS $$ SELECT '"+at+"'::timestamptz $$");}
 UUID proposal(UUID id){var plan=sessions.request(id,member.id(),new ListenerSessions.Proposal(UUID.randomUUID()));return(UUID)((Map<?,?>)plan.get("extension")).get("id");}
 @Test @Tag("happy") void thirtyMinutesStartAtActivationAndInitialBoundaryExplainsThePlan(){var r=active();assertThat(Duration.between(r.activatedAt(),r.plannedEndsAt())).isEqualTo(Duration.ofMinutes(30));assertThat(r.plannedSeconds()).isEqualTo(1800);assertThat(db.queryForList("SELECT body FROM messages WHERE conversation_id=? AND message_kind='SYSTEM'",String.class,r.conversationId())).anyMatch(body->body.contains("30 minutes from activation"));}
 @Test @Tag("happy") void oneTenMinuteExtensionRequiresBothConsentsAndRetriesNeverAddMore(){var r=active();UUID e=proposal(r.id());assertThat(live.get(r.id(),member.id()).plannedEndsAt()).isEqualTo(r.plannedEndsAt());sessions.decide(r.id(),e,member.id(),true);assertThat(live.get(r.id(),member.id()).plannedEndsAt()).isEqualTo(r.plannedEndsAt());sessions.decide(r.id(),e,listener.id(),true);var extended=live.get(r.id(),member.id());assertThat(extended.plannedEndsAt()).isEqualTo(r.plannedEndsAt().plusSeconds(600));assertThat(extended.extensionSecondsUsed()).isEqualTo(600);sessions.decide(r.id(),e,listener.id(),true);assertThat(live.get(r.id(),member.id()).plannedEndsAt()).isEqualTo(extended.plannedEndsAt());assertThatThrownBy(()->sessions.request(r.id(),listener.id(),new ListenerSessions.Proposal(UUID.randomUUID()))).hasMessageContaining("existing extension");}
 @Test @Tag("malicious") void anotherAccountCannotInspectApproveOrReadFeedback(){var r=active();UUID e=proposal(r.id());var stranger=PhaseIFixtures.member(db,users,tokens);assertThatThrownBy(()->sessions.plan(r.id(),stranger.id())).isInstanceOf(LiveSupportException.class);assertThatThrownBy(()->sessions.decide(r.id(),e,stranger.id(),true)).isInstanceOf(LiveSupportException.class);assertThatThrownBy(()->sessions.feedback(r.id(),listener.id())).isInstanceOf(LiveSupportException.class);}
 @Test @Tag("confused") void expiredOrDeclinedConsentCannotReopenOrExtend(){var r=active();UUID e=proposal(r.id());Instant expiry=db.queryForObject("SELECT expires_at FROM listener_session_extensions WHERE id=?",OffsetDateTime.class,e).toInstant();clock(expiry);assertThatThrownBy(()->sessions.decide(r.id(),e,listener.id(),true)).hasMessageContaining("no longer open");assertThat(live.get(r.id(),member.id()).plannedEndsAt()).isEqualTo(r.plannedEndsAt());}
 @Test @Tag("happy") void explicitDeclineLeavesOriginalDeadlineAndDoesNotInviteRepeatedProposals(){var r=active();UUID e=proposal(r.id());sessions.decide(r.id(),e,listener.id(),false);assertThat(db.queryForObject("SELECT status FROM listener_session_extensions WHERE id=?",String.class,e)).isEqualTo("DECLINED");assertThat(live.get(r.id(),member.id()).plannedEndsAt()).isEqualTo(r.plannedEndsAt());}
 @Test @Tag("malicious") void nextBookingWinsBeforeSecondConsentAndExtraTimeIsNeverPromised(){var r=active();UUID e=proposal(r.id());Instant next=r.plannedEndsAt().plusSeconds(450);window(next,next.plusSeconds(3600));var other=PhaseIFixtures.member(db,users,tokens);bookings.reserve(other.id(),new ListenerBookings.Reservation(listener.id(),next,UUID.randomUUID(),false));assertThatThrownBy(()->sessions.decide(r.id(),e,listener.id(),true)).hasMessageContaining("prevent extra time");assertThat(db.queryForObject("SELECT status FROM listener_session_extensions WHERE id=?",String.class,e)).isEqualTo("UNAVAILABLE");assertThat(live.get(r.id(),member.id()).plannedEndsAt()).isEqualTo(r.plannedEndsAt());}
 @Test @Tag("malicious") void timerCannotBeForgedWithoutBothDatabaseConsentRecords(){var r=active();UUID e=proposal(r.id());db.execute("SAVEPOINT forged_duration");try{assertThatThrownBy(()->db.update("UPDATE live_support_requests SET planned_ends_at=planned_ends_at+INTERVAL '10 minutes',extension_seconds_used=600 WHERE id=?",r.id())).isInstanceOf(org.springframework.dao.DataIntegrityViolationException.class);}finally{db.execute("ROLLBACK TO SAVEPOINT forged_duration");}db.execute("SAVEPOINT forged_consent");try{assertThatThrownBy(()->db.update("UPDATE listener_session_extensions SET status='APPLIED' WHERE id=?",e)).isInstanceOf(org.springframework.dao.DataIntegrityViolationException.class);}finally{db.execute("ROLLBACK TO SAVEPOINT forged_consent");}assertThat(live.get(r.id(),member.id()).plannedEndsAt()).isEqualTo(r.plannedEndsAt());}
 @Test @Tag("creative") void interruptionAndQualificationLossOverrideExtension(){var r=active();UUID e=proposal(r.id());db.update("UPDATE live_support_requests SET member_seen_at=clock_timestamp()-INTERVAL '50 seconds' WHERE id=?",r.id());assertThatThrownBy(()->sessions.decide(r.id(),e,listener.id(),true)).isInstanceOf(LiveSupportException.class);assertThat(live.get(r.id(),member.id()).status()).isEqualTo("INTERRUPTED");assertThat(live.get(r.id(),member.id()).plannedEndsAt()).isEqualTo(r.plannedEndsAt());}
 @Test @Tag("happy") void advanceWarningsAreDeduplicatedAndSendingEndsAtAuthoritativeDeadline(){var r=active();clock(r.plannedEndsAt().minusSeconds(300));maintenance.run();maintenance.run();assertThat(db.queryForObject("SELECT count(*) FROM listener_session_warning_notices WHERE session_id=?",Integer.class,r.id())).isEqualTo(1);clock(r.plannedEndsAt().minusSeconds(60));maintenance.run();assertThat(db.queryForObject("SELECT count(*) FROM listener_session_warning_notices WHERE session_id=?",Integer.class,r.id())).isEqualTo(2);clock(r.plannedEndsAt());assertThatThrownBy(()->live.requireSending(r.conversationId(),member.id(),UUID.randomUUID())).hasMessageContaining("only permitted");assertThat(live.get(r.id(),member.id()).status()).isEqualTo("COMPLETED");assertThat(live.get(r.id(),member.id()).reasonCode()).isEqualTo("PLANNED_DURATION_ENDED");}
 @Test @Tag("happy") void optionalFeedbackIsOwnedCorrectableAndSeparateFromReports(){var r=active();live.end(r.id(),member.id());var input=new ListenerSessions.Feedback(true,true,null,0);assertThat(sessions.saveFeedback(r.id(),member.id(),input).get("revision")).isEqualTo(1L);assertThat(sessions.saveFeedback(r.id(),member.id(),input).get("revision")).isEqualTo(1L);assertThat(sessions.saveFeedback(r.id(),member.id(),new ListenerSessions.Feedback(false,true,true,1)).get("revision")).isEqualTo(2L);assertThatThrownBy(()->sessions.saveFeedback(r.id(),member.id(),input)).hasMessageContaining("Reload");assertThatThrownBy(()->sessions.feedback(r.id(),listener.id())).hasMessageContaining("Only the member");assertThat(db.queryForObject("SELECT count(*) FROM reports WHERE reporter_id=?",Integer.class,member.id())).isZero();sessions.removeFeedback(r.id(),member.id());assertThat(sessions.feedback(r.id(),member.id())).isEmpty();}
 @Test @Tag("confused") void feedbackNeverCollectsAnEmptyRecordOrRunsDuringLiveConversation(){var r=active();assertThatThrownBy(()->sessions.saveFeedback(r.id(),member.id(),new ListenerSessions.Feedback(true,null,null,0))).hasMessageContaining("after a completed");live.end(r.id(),member.id());assertThatThrownBy(()->sessions.saveFeedback(r.id(),member.id(),new ListenerSessions.Feedback(null,null,null,0))).isInstanceOf(IllegalArgumentException.class);assertThat(sessions.feedback(r.id(),member.id())).isEmpty();}
 @Test @Tag("happy") void sameListenerRepeatIsVoluntaryAndRevalidatesQualification(){var r=active();live.end(r.id(),member.id());assertThat(sessions.repeat(r.id(),member.id()).items()).isNotEmpty();assertThat(db.queryForObject("SELECT count(*) FROM listener_bookings WHERE member_id=?",Integer.class,member.id())).isZero();db.update("UPDATE listener_live_authorizations SET revoked_at=clock_timestamp() WHERE listener_id=?",listener.id());assertThatThrownBy(()->sessions.repeat(r.id(),member.id())).hasMessageContaining("Independent current");}
 @Test @Tag("creative") void readinessIsNotInventedAndNoShowReasonsAreDistinct(){UUID first=(UUID)bookings.reserve(member.id(),new ListenerBookings.Reservation(listener.id(),start,UUID.randomUUID(),false)).get("id");clock(start.plusSeconds(600));bookings.reconcile();assertThat(bookings.view(first,member.id()).get("status")).isEqualTo("MEMBER_NO_SHOW");Instant second=start.plusSeconds(2400);UUID b=(UUID)bookings.reserve(member.id(),new ListenerBookings.Reservation(listener.id(),second,UUID.randomUUID(),false)).get("id");clock(second);bookings.checkin(b,member.id());clock(second.plusSeconds(600));bookings.reconcile();assertThat(bookings.view(b,member.id()).get("status")).isEqualTo("EXPIRED");assertThat(bookings.view(b,member.id()).get("reason_code")).isEqualTo("HANDOFF_NOT_COMPLETED");Instant third=second.plusSeconds(2400);UUID c=(UUID)bookings.reserve(member.id(),new ListenerBookings.Reservation(listener.id(),third,UUID.randomUUID(),false)).get("id");live.setAvailability(listener.id(),listener.session(),0,false,live.availability(listener.id(),listener.session()).leaseId());clock(third);bookings.checkin(c,member.id());clock(third.plusSeconds(600));bookings.reconcile();assertThat(bookings.view(c,member.id()).get("status")).isEqualTo("LISTENER_NO_SHOW");assertThat(db.queryForObject("SELECT count(*) FROM live_support_requests WHERE member_id=?",Integer.class,member.id())).isZero();}
 @Test @Tag("creative") void legacyUnboundedContractNeverReceivesRetroactiveTimer(){var legacy=new LiveSupportService(db,access,settings,rates,messaging);var r=legacy.create(member.id(),UUID.randomUUID(),listener.id());legacy.accept(r.id(),listener.id());var active=legacy.activate(r.id(),member.id());clock(p.now().plusSeconds(7200));assertThat(live.get(active.id(),member.id()).status()).isEqualTo("ACTIVE");assertThat(live.get(active.id(),member.id()).plannedEndsAt()).isNull();assertThatThrownBy(()->proposal(active.id())).hasMessageContaining("unavailable");}
 @Test @Tag("happy") void accountErasureRemovesFeedbackConsentAndSessionNotices(){var r=active();UUID e=proposal(r.id());sessions.decide(r.id(),e,listener.id(),true);live.end(r.id(),member.id());sessions.saveFeedback(r.id(),member.id(),new ListenerSessions.Feedback(true,null,null,0));accounts.erase(member.id());assertThat(db.queryForObject("SELECT count(*) FROM listener_session_extensions WHERE session_id=?",Integer.class,r.id())).isZero();assertThat(db.queryForObject("SELECT count(*) FROM listener_session_feedback WHERE session_id=?",Integer.class,r.id())).isZero();}
 @Test @Tag("malicious") void historyShowsOnlyOwnedParticipationAndOwnFeedbackState()throws Exception{var r=active();live.end(r.id(),member.id());sessions.saveFeedback(r.id(),member.id(),new ListenerSessions.Feedback(true,null,null,0));var own=mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/api/v1/listener-support/history").header("Authorization","Bearer "+member.token())).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isOk()).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath("$[0].feedbackSaved").value(true)).andReturn();assertThat(own.getResponse().getContentAsString()).doesNotContain("helpful");mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/api/v1/listener-support/history").header("Authorization","Bearer "+listener.token())).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isOk()).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath("$[0].feedbackSaved").value(false));var stranger=PhaseIFixtures.member(db,users,tokens);mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/api/v1/listener-support/history").header("Authorization","Bearer "+stranger.token())).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isOk()).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath("$.length()").value(0));}
}
